'use strict';
const $=id=>document.getElementById(id);
const colors={PROCESSING:'#2dd4bf',SETUP:'#a78bfa',LOADING:'#38bdf8',UNLOADING:'#38bdf8',CYCLE_CHANGE:'#38bdf8',IDLE_AVAILABLE:'#4b6078',OFF_SHIFT:'#64748b',ON_BREAK:'#c084fc',CARRYING:'#fbbf24',WALKING:'#60a5fa',IDLE_AT_LOCATION:'#60a5fa'};
const labels={PROCESSING:'בעיבוד',SETUP:'הכנה',LOADING:'טעינה',UNLOADING:'פריקה',CYCLE_CHANGE:'החלפת מחזור',IDLE_AVAILABLE:'פנויה',OFF_SHIFT:'מחוץ למשמרת',ON_BREAK:'בהפסקה',CARRYING:'נושא חלקים',WALKING:'בהליכה',IDLE_AT_LOCATION:'פנוי',WAITING_FOR_WORKER_LOAD:'ממתינה לטעינה',WAITING_FOR_CYCLE_CHANGE:'ממתינה להחלפה',WAITING_FOR_WORKER_UNLOAD:'ממתינה לפריקה'};
let liveData=null,liveJobId=null,computing=false;
let connected=false,result=null,surfaceData=null,currentTab='machines',selected=null,time=0,playing=false,lastFrame=0,taskId=null,yaw=.68;
let machineLayout=[],tracks=new Map(),nodeCoords=[],hitboxes=[],surfaceHits=[],heatHits=[];
const format=(n,d=1)=>n===null||n===undefined||!Number.isFinite(n)?'—':n.toLocaleString('he-IL',{maximumFractionDigits:d});
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error)}
async function api(path,body){const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!response.ok){let message='שגיאת שרת';try{message=(await response.json()).message}catch{}const error=Error(message);error.status=response.status;throw error}return response.json()}
function config(){return{algorithm:$('algorithm').value,arrival_load:+$('arrivalLoad').value,batch_size:+$('batchSize').value,horizon_days:+$('horizon').value,seed:+$('seed').value,trace_days:7,warmup_days:+$('warmup').value}}
function busy(value){computing=value;document.body.classList.toggle('busy',value);for(const id of ['run','scenario','grid'])$(id).disabled=value||!connected;$('cancel').hidden=!value;for(const id of ['play','next','scrub','seek'])$(id).disabled=value||!result||!!liveData;for(const id of ['upload','savedSurface'])$(id).disabled=value;$('download').disabled=value||!result;$('downloadSurface').disabled=value||!surfaceData;}
async function run(mode){playing=false;liveData=null;if(!connected){notice('הפעל את run_factory.py במחשב, או טען קובץ תוצאה שמור.',true);return}busy(true);$('progress').textContent='מתחיל הרצה…';try{const data=await api('/api/run',{mode,config:config(),replications:+$('replications').value,grid:$('gridValues').value.split(',').map(Number)});taskId=data.id;await poll()}catch(e){notice(e.message,true);busy(false)}}
async function poll(){
 let task;try{task=await api('/api/tasks/'+taskId)}catch(e){if(e.status===404){taskId=null;if(result)loadRun(result);busy(false);notice('המשימה אינה קיימת עוד, ייתכן שהשרת הופעל מחדש. ניתן להתחיל הרצה חדשה.',true);return}notice('החיבור נקטע; מנסה להתחבר שוב להרצה הקיימת. '+e.message,true);setTimeout(poll,3000);return}
 $('progress').textContent=task.message;
 if(task.live)renderLive(task.live,task.status);
 if(task.surface){surfaceData=task.surface;renderSurfaces()}
 if(task.status==='RUNNING'){setTimeout(poll,900);return}
 if(task.result?.trace)loadRun(task.result);
 else if(task.result){if(result)loadRun(result);loadSurface(task.result)}
 else if(result)loadRun(result);
 taskId=null;busy(false);
 if(task.status==='COMPLETE')$('progress').textContent='ההרצה הסתיימה ונשמרה.';
 else notice(task.message||'ההרצה נעצרה; מוצג המצב האחרון הזמין.',true);
}

function loadRun(data){liveData=null;$('liveProgress').textContent='מצב שחזור — המדדים החיים האחרונים מתייחסים לחישוב שהסתיים. פרטי הישויות במפה מתייחסים לשעון השחזור.';renderSurfaces();if(!data||!Array.isArray(data.machines)||!data.trace||!Array.isArray(data.trace.intervals)||!Array.isArray(data.jobs))throw Error('קובץ תוצאה אינו תואם למנוע הייצור');result=data;const ref=data.flow_reference;$('flowReference').textContent=ref?`חסם תחתון לעיבוד בלבד: ${format(ref.mean_lower_bound_min===null?null:ref.mean_lower_bound_min/60)} שעות · זמן בפועל / חסם: ${format(ref.actual_to_lower_bound_ratio,2)} · מעל החסם: ${format(ref.excess_over_lower_bound_percent)}% · ללא תורים, Setup, טיפול ידני ושינוע; אינו אופטימום מוכח.`:'לקובץ הישן אין מדד ייחוס. הרצה חדשה תחשב חסם תחתון לעיבוד בלבד.';if(!surfaceData||surfaceData.single_run){surfaceData={single_run:true,points:[{arrival_load:data.config.arrival_load,batch_size:data.config.batch_size,warmup_days:data.config.warmup_days,seed:data.config.seed,dataset_sha256:data.dataset_sha256,code_sha256:data.engine_source_sha256,algorithms:{[data.config.algorithm]:{mean:data.mean_flow_min,n:1,status:'SINGLE_RUN_NO_CI'}},status:'SINGLE_RUN_NO_CI'}]};if(['FIFO','SPT'].includes(data.config.algorithm))$('surfaceAlgorithm').value=data.config.algorithm;renderSurfaces();$('pointDetails').textContent='ריצה בודדת: נקודה אחת בלבד. לקבלת משטח הפעילו רשת תרחישים.';}syncRunControls(data.config);$('warmup').value=data.config.warmup_days;$('seed').value=data.config.seed;$('algorithm').value=data.config.algorithm;machineLayout=data.machines;nodeCoords=data.trace.nodes;tracks=new Map();for(const interval of data.trace.intervals){if(!tracks.has(interval.entity))tracks.set(interval.entity,[]);tracks.get(interval.entity).push(interval)}for(const list of tracks.values())list.sort((a,b)=>a.start-b.start);time=data.trace.start_min||0;playing=false;selected=null;$('scrub').min=time;$('seek').min=time;$('flow').textContent=format(data.mean_flow_min===null?null:data.mean_flow_min/60);$('complete').textContent=format(data.completed_measurement_jobs,0);$('cohort').textContent='מתוך '+format(data.measurement_jobs,0)+' עבודות ששוחררו בחלון';$('utilization').textContent=format(data.machine_utilization*100)+'%';$('wip').textContent=format(data.mean_wip);$('machineCount').textContent=machineLayout.length+' מכונות';$('scrub').max=data.trace.end_min;$('seek').max=data.trace.end_min;$('seek').disabled=false;$('scrub').disabled=false;$('play').disabled=false;$('next').disabled=false;$('download').disabled=false;$('downloadSurface').disabled=false;$('play').textContent='▶ הפעל שחזור';$('empty').style.display='none';$('replayLimit').textContent='שחזור מיום '+format((data.trace.start_min||0)/1440)+' עד יום '+format(data.trace.end_min/1440);$('provenance').textContent='World '+data.world_version+' · Python '+data.environment.python+' · Seed '+data.config.seed+' · Dataset '+data.dataset_sha256.slice(0,12);$('loadMetrics').textContent='Available machine utilization: '+format((data.machine_available_utilization??data.machine_utilization)*100)+'% · מכונות זמינות לעיבוד אוטונומי 24/7 · Bottleneck '+format(data.bottleneck_utilization*100)+'% · Worker available '+format(data.worker_available_utilization*100)+'% · Mean queue '+format(data.mean_queue)+' · Throughput '+format(data.throughput_jobs_per_day)+' עבודות/יום · Setup workers '+format(data.setup_worker_utilization*100)+'%'+' · Effective arrivals '+format(data.demand_provenance?.effective_arrival_rate,3)+'/יום';const drift=data.operating_point?.candidates?.[String(data.config.baseline_calibration_multiplier)]?.wip_slope_ci95_across_replications;if(drift?.[0]>0)$('loadMetrics').textContent+=' · אזהרה: מגמת WIP חיובית נותרה; יציבות לא הוכחה';renderFamilyMetrics(data);notice('ריצה בודדת · '+data.status+' · זמן השהייה כולל ניקוז; ניצולת, תורים ותפוקה נמדדים בחלון בלבד. השחזור מוגבל לחלון המוצג.');drawFloor();renderEntities();updateClock()}
function intervalAt(id,t=time){if(liveData){const r=[...liveData.machines,...liveData.workers].find(x=>x.id===id);return r?{...r,start:r.since,end:liveData.time}:null;}const list=tracks.get(id)||[];let l=0,r=list.length-1,found=null;while(l<=r){const m=(l+r)>>1;if(list[m].start<=t){found=list[m];l=m+1}else r=m-1}return found&&t<=found.end?found:null}
function position(interval){if(!interval)return null;if(interval.path?.length){const points=interval.path.map(i=>nodeCoords[i]);let total=0;for(let i=1;i<points.length;i++)total+=Math.abs(points[i][0]-points[i-1][0])+Math.abs(points[i][1]-points[i-1][1]);let remaining=Math.max(0,Math.min(1,(time-interval.start)/((interval.move_end??interval.end)-interval.start||1)))*total;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],d=Math.abs(b[0]-a[0])+Math.abs(b[1]-a[1]);if(remaining<=d){const f=d?remaining/d:0;return[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f]}remaining-=d}return points.at(-1)}return nodeCoords[interval.node]||null}
function transform(){const xs=machineLayout.map(m=>m.x+m.w),ys=machineLayout.map(m=>m.y+m.h);const maxX=Math.max(1,...xs),maxY=Math.max(1,...ys);const canvas=$('floor');const scale=1400/maxX;const wanted=Math.round(maxY*scale+110);if(canvas.height!==wanted)canvas.height=wanted;return {scale,x:50,y:70}}
function drawFloor(){const canvas=$('floor'),tr=transform(),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#0b1624';ctx.fillRect(0,0,canvas.width,canvas.height);const xy=p=>[tr.x+p[0]*tr.scale,tr.y+p[1]*tr.scale];ctx.strokeStyle='#14273b';ctx.lineWidth=1;for(let x=20;x<1500;x+=40){ctx.beginPath();ctx.moveTo(x,20);ctx.lineTo(x,canvas.height-20);ctx.stroke()}for(let y=20;y<canvas.height;y+=40){ctx.beginPath();ctx.moveTo(20,y);ctx.lineTo(1480,y);ctx.stroke()}ctx.font='18px Segoe UI';ctx.fillStyle='#7e96af';ctx.textAlign='center';ctx.fillText('CALIBRATED PRODUCTION WORLD · '+[...new Set(machineLayout.map(m=>m.machine_family).filter(Boolean))].join(' / '),720,38);const border=xy([1150,0])[0];ctx.setLineDash([6,8]);ctx.strokeStyle='#365069';ctx.beginPath();ctx.moveTo(border,55);ctx.lineTo(border,canvas.height-20);ctx.stroke();ctx.setLineDash([]);hitboxes=[];for(const m of machineLayout){const [x,y]=xy([m.x,m.y]),w=m.w*tr.scale,h=m.h*tr.scale;const state=intervalAt(m.id)?.state||'IDLE_AVAILABLE',color=colors[state]||'#fbbf24';ctx.fillStyle=color+'22';ctx.strokeStyle=selected?.id===m.id?'#fff':color;ctx.lineWidth=selected?.id===m.id?3:1.3;ctx.beginPath();ctx.roundRect(x,y,w,h,4);ctx.fill();ctx.stroke();ctx.fillStyle=color;ctx.fillRect(x+5,y+6,4,Math.max(4,h-12));ctx.fillStyle='#dce9f7';ctx.font='18px Consolas,monospace';ctx.textAlign='center';ctx.fillText(m.id,x+w/2,y+h/2+5);if(selected?.id===m.id){ctx.font='16px Segoe UI';ctx.fillText(m.machine_family==='Milling'?'Milling '+(m.axis_capability||'')+' axes':(m.machine_family||''),x+w/2,y-8);}hitboxes.push({x,y,w,h,type:'machines',id:m.id})}if(result||liveData){const occupied=new Map();for(const w of (liveData?.workers||result.workers)){const interval=intervalAt(w.id);if(!interval||interval.state==='OFF_SHIFT')continue;const pos=position(interval);if(!pos)continue;let [x,y]=xy(pos);const place=Math.round(x)+','+Math.round(y),slot=occupied.get(place)||0;occupied.set(place,slot+1);if(slot){const angle=slot*2.39996,radius=13*Math.ceil(slot/6);const ox=x,oy=y;x+=Math.cos(angle)*radius;y+=Math.sin(angle)*radius;ctx.strokeStyle='#60a5fa70';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(x,y);ctx.stroke()}if(interval.path&&selected?.id===w.id){ctx.strokeStyle='#60a5fa80';ctx.lineWidth=3;ctx.beginPath();interval.path.forEach((n,i)=>{const p=xy(nodeCoords[n]);i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.stroke()}ctx.fillStyle=colors[interval.state]||'#60a5fa';ctx.strokeStyle='#091523';ctx.lineWidth=2;ctx.beginPath();if(w.kind?.startsWith('setup'))ctx.rect(x-8,y-8,16,16);else ctx.arc(x,y,8,0,Math.PI*2);ctx.fill();ctx.stroke();if(selected?.id===w.id){ctx.strokeStyle='#fff';ctx.beginPath();ctx.arc(x,y,13,0,Math.PI*2);ctx.stroke();ctx.font='18px Consolas';ctx.fillStyle='#fff';ctx.fillText(w.id,x,y-18)}hitboxes.push({x:x-10,y:y-10,w:20,h:20,type:'workers',id:w.id})}}const p=xy([1150,200]);ctx.fillStyle='#9dafc6';ctx.font='12px Segoe UI';ctx.fillText('HANDOFF',p[0],p[1]-15)}
function jobState(j){if(time<j.release)return'טרם שוחררה';if(j.complete!==null&&time>=j.complete)return'הושלמה';const active=[...tracks.keys()].map(id=>intervalAt(id)).filter(i=>i?.job===j.id);return [...new Set(active.map(i=>labels[i.state]||i.state))].join(' / ')||'ממתינה — ללא פעילות מתועדת ברגע זה'}
function batchState(b){if(time<b.ready)return'טרם הגיעה';const initial=result.trace.initial?.batches?.[b.id];if(initial?.state==='COMPLETE')return'הושלמה';if(initial?.state==='SPLIT')return'פוצלה';const active=[...tracks.keys()].map(id=>intervalAt(id)).find(i=>i?.batch===b.id);if(active)return labels[active.state]||active.state;const events=(result?.trace.events||[]).filter(e=>e.batch===b.id&&e.time<=time);if(events.some(e=>e.kind==='split'))return'פוצלה';if(events.filter(e=>e.kind==='parts_unloaded').reduce((n,e)=>n+e.hi-e.lo,initial?.completed||0)>=b.hi-b.lo)return'הושלמה';return'ממתינה';}
function renderEntities(){const q=$('search').value.toLowerCase();const list=liveData?(currentTab==='batches'?liveData.jobs.flatMap(j=>j.batches.map(b=>({...b,job:j.id}))):liveData[currentTab]):result?result[currentTab]:currentTab==='machines'?machineLayout:[];const shown=(list||[]).filter(e=>String(e.id).toLowerCase().includes(q));$('entities').innerHTML=shown.map(e=>{const state=liveData?(currentTab==='jobs'?[...new Set(e.batches.map(b=>labels[b.state]||b.state))].join(' / '):(labels[e.state]||e.state)):currentTab==='jobs'?jobState(e):currentTab==='batches'?batchState(e):labels[intervalAt(e.id)?.state]||(currentTab==='workers'?'מחוץ למשמרת':'פנויה');const id=String(e.id);return`<button class="entity ${selected?.id===id?'selected':''}" data-id="${escape(id)}"><b dir="ltr">${escape(currentTab==='workers'?id.split('_').slice(-1)[0].slice(0,8):['jobs','batches'].includes(currentTab)?id.slice(-18):id)}</b><span>${escape(state)}</span></button>`}).join('');for(const button of $('entities').querySelectorAll('button'))button.onclick=()=>select(currentTab,button.dataset.id);renderInspector()}
function select(type,id){if(liveData&&type==='jobs'){liveJobId=id;renderLiveJob()}selected={type,id};currentTab=type;for(const b of document.querySelectorAll('[data-tab]'))b.setAttribute('aria-selected',String(b.dataset.tab===type));renderEntities();drawFloor()}
function renderInspector(){if(!selected)return;if(liveData){if(selected.type==='jobs'){const j=liveData.jobs.find(j=>j.id===selected.id);$('inspector').innerHTML=j?'<h3>'+escape(j.id)+'</h3><p>משפחה: '+escape(j.item)+' · כמות: '+j.quantity+'</p><p>שהייה עד כה: '+format((liveData.time-j.release)/60)+' שעות</p>'+j.route.map(op=>'<p>'+escape(op)+': '+(j.operation_counts[op]||0)+' / '+j.quantity+' נפרקו</p>').join(''):'העבודה אינה פעילה עוד.';return}const r=[...liveData.machines,...liveData.workers,...liveData.jobs.flatMap(j=>j.batches)].find(r=>r.id===selected.id);$('inspector').innerHTML=r?'<h3>'+escape(r.id)+'</h3>'+[['מצב',labels[r.state]||r.state],['עבודה',r.job],['מנה',r.batch],['עובד',r.worker],['סוג Setup',r.setup_type],['מעבר הכנה',r.from_class? r.from_class+' → '+r.to_class:null],['זמן במצב הנוכחי',format(liveData.time-r.since)+' דקות']].filter(x=>x[1]!=null).map(([k,v])=>'<p>'+k+': <b>'+escape(v)+'</b></p>').join(''):'בחרו עבודה בטבלת המצב החי.';return;}const row=(result?.[selected.type]||machineLayout).find(x=>x.id===selected.id);if(!row)return;const interval=intervalAt(row.id);let lines=[];if(selected.type==='machines'){lines=[['מחלקה',row.machine_family||row.department],['מצב',labels[interval?.state]||'פנויה'],['עבודה',interval?.job||'—'],['תת־מנה',interval?.batch||'—'],['עובד מטפל',interval?.worker||'—'],['סוג Setup',interval?.setup_type||'—'],['מעבר הכנה',interval?.from_class?interval.from_class+' → '+interval.to_class:'—'],['זמן במצב',interval?format(time-interval.start)+' דקות':'—']]}else if(selected.type==='workers'){lines=[['מחלקה',row.machine_family||row.department],['מצב',labels[interval?.state]||'מחוץ למשמרת'],['משמרת',(row.kind.includes('setup')?'Setup · ':'')+(row.kind.endsWith('day')?'יום':'לילה')],['מכונה',interval?.machine||'—'],['תת־מנה',interval?.batch||'—'],['כשירויות',row.skills.join(', ')]]}else if(selected.type==='batches'){lines=[['מצב בשחזור',batchState(row)],['עבודת מקור',row.job],['כמות',row.hi-row.lo],['מזהי חלקים',row.lo+'–'+(row.hi-1)],['פעולה',result.jobs.find(j=>j.id===row.job)?.route[row.op_index]],['מנה מקורית',row.parent||'מנה ראשית'],['מכונת יעד',row.target||'לפי ההקצאה']]}else{const unloaded=(result.trace.events||[]).filter(e=>e.kind==='parts_unloaded'&&e.job===row.id&&e.time<=time&&e.operation===row.route.at(-1)).reduce((n,e)=>n+e.hi-e.lo,0);const prior=result.trace.initial?.job_completed?.[row.id]||0;lines=[['מצב',jobState(row)],['פריט',row.item],['כמות מקורית',row.quantity],['הושלמו בשחזור',prior+unloaded],['ניתוב',row.route.join(' → ')],['שחרור',format(row.release/60)+' שעות'],['זמן שהייה בסוף הריצה המלאה',row.complete!==null?format((row.complete-row.release)/60)+' שעות':'—']];const batches=(result.batches||[]).filter(b=>b.job===row.id&&b.ready<=time);lines.push(['תתי־מנות שנוצרו עד כאן',batches.length]);lines.push(['תת־מנה אחרונה',batches.at(-1)?.id||'—'])}$('inspector').innerHTML='<h3 dir="ltr">'+escape(row.id)+'</h3>'+lines.map(([k,v])=>`<p>${escape(k)}: <b>${escape(v)}</b></p>`).join('');if(selected.type==='jobs')renderOperationHistory(row)}
function updateClock(){if(result){const released=result.jobs.filter(j=>j.release<=time).length,completed=result.jobs.filter(j=>j.complete!==null&&j.complete<=time).length;let snapshot=null;for(const x of result.trace.snapshots||[]){if(x.time>time)break;snapshot=x}$('liveCounts').textContent='בזמן השחזור · Released '+released+' · Completed '+completed+' · Current WIP '+(released-completed)+' · Queued batches / requests '+(snapshot?.queue??'—');}renderQueueCounts(snapshotAtTime()?.ready_queue_by_family);if(!result)return;const start=new Date(result.config.start_date+'Z');const date=new Date(start.getTime()+time*60000);$('clock').textContent=date.toISOString().slice(0,16).replace('T',' · ');$('scrub').value=time;if(document.activeElement!==$('seek'))$('seek').value=time.toFixed(2)}
function frame(stamp){const dt=lastFrame?(stamp-lastFrame)/1000:0;lastFrame=stamp;if(playing&&result){time=Math.min(result.trace.end_min,time+dt*(+$('speed').value)/60);if(time>=result.trace.end_min){playing=false;$('play').textContent='▶ הפעל שחזור'}drawFloor();updateClock();if(Math.floor(stamp/400)!==Math.floor((stamp-dt*1000)/400))renderEntities()}requestAnimationFrame(frame)}
function loadSurface(data){liveData=null;surfaceData=data.points?data:{points:[data],grid:[data.arrival_load],purpose:data.purpose};if(!Array.isArray(surfaceData.points))throw Error('Invalid experiment file');$('downloadSurface').disabled=false;renderSurfaces();$('surface').scrollIntoView({behavior:'smooth',block:'center'});notice(data.purpose?'נתוני בדיקת קבלה מבוקרת — אינם אומדן של רצפת הייצור.':'תוצאות ניסוי לאופק מוגדר נטענו; אין אישור ליציבות או לדירוג האלגוריתמים.')}
function cellValue(p){const algo=$('surfaceAlgorithm').value,summary=p.algorithms?.[algo],base=p.algorithms?.FIFO;if(!summary||!Number.isFinite(summary.mean))return null;const mode=$('view').value;if(mode==='delta')return base?.mean!==null&&base?.mean!==undefined?(summary.mean-base.mean)/60:null;if(mode==='improvement')return base?.mean?100*(base.mean-summary.mean)/base.mean:null;return summary.mean/60}
