function renderSurfaces(){const names=[...new Set((surfaceData?.points||[]).flatMap(p=>Object.keys(p.algorithms||{})))];const current=$('surfaceAlgorithm').value;if(names.length){$('surfaceAlgorithm').innerHTML=names.map(a=>`<option value="${escape(a)}">${escape(a)}</option>`).join('');$('surfaceAlgorithm').value=names.includes(current)?current:names[0];}drawSurface();drawHeatmap();const points=surfaceData?.points||[];$('pointSelect').innerHTML='<option value="">בחירת נקודה לפירוט</option>'+points.map((p,i)=>'<option value="'+i+'">הגעה ×'+p.arrival_load+' · גודל ×'+p.batch_size+'</option>').join('');$('resultsTable').innerHTML=points.flatMap(p=>Object.entries(p.algorithms||{}).map(([a,s])=>`<tr><td>${p.arrival_load}</td><td>${p.batch_size}</td><td>${escape(a)}</td><td>${format(s.mean===null?null:s.mean/60)}</td><td dir="ltr">${s.ci95?s.ci95.map(x=>format(x/60)).join(' – '):'—'}</td><td>${s.n||0}</td><td>${p.warmup_days??'—'}</td><td class="${pointUnconfirmed(p)?'warning':''}">${escape(s.status||p.status)}</td></tr>`)).join('');const compat=surfaceData?.source_compatibility;$('surfaceProvenance').textContent=compat&&(!compat.matches_current_code||!compat.matches_current_world)?'נתוני ארכיון: הקוד או העולם שונים מהגרסה הפעילה. הנתונים אינם אימות של הגרסה הנוכחית.':surfaceData?'זהות מקור הניסוי: '+(surfaceData.code_sha256||points[0]?.code_sha256||'לא נמסרה').slice(0,12)+' · יציבות לא הוכחה; רווחי הסמך מוצגים ללא קיטום.':'';if(points.length)$('pointDetails').textContent=pointText(points[0]);else $('pointDetails').textContent='תוצאות יופיעו לאחר הניסוי. אין כרגע משטח מחקר מחושב.'}
function color(v,min,max){const f=(v-min)/(max-min||1);return`hsl(${175-140*f} 70% 55%)`}
function drawSurface(){const c=$('surface'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);surfaceHits=[];const pts=surfaceData?.points||[];const values=pts.map(cellValue).filter(x=>x!==null),min=Math.min(0,...values),max=Math.max(1,...values);const maxA=Math.max(1.5,...pts.map(p=>p.arrival_load)),maxB=Math.max(1.5,...pts.map(p=>p.batch_size));const project=(a,b,z)=>{const x=a/maxA-.5,y=b/maxB-.5;return[400+(x*Math.cos(yaw)-y*Math.sin(yaw))*430,290+(x*Math.sin(yaw)+y*Math.cos(yaw))*110-(z-min)/(max-min)*180]};ctx.lineWidth=1;ctx.strokeStyle='#36516d';ctx.font='14px Segoe UI';ctx.textAlign='center';const origin=project(0,0,min);for(const [p,label]of[[project(maxA,0,min),'Arrival load ×'],[project(0,maxB,min),'Batch size ×'],[project(0,0,max),metricLabel()]]){ctx.beginPath();ctx.moveTo(...origin);ctx.lineTo(...p);ctx.stroke();ctx.fillStyle='#b5c8de';ctx.fillText(label,p[0],p[1]+(label===metricLabel()?-16:24))}for(const a of [...new Set(pts.map(p=>p.arrival_load))]){const p=project(a,0,min);ctx.fillText(format(a),p[0],p[1]+15)}for(const b of [...new Set(pts.map(p=>p.batch_size))]){const p=project(0,b,min);ctx.fillText(format(b),p[0],p[1]+15)}for(let i=0;i<=4;i++){const z=min+(max-min)*i/4,p=project(0,0,z);ctx.fillStyle='#b5c8de';ctx.fillText(format(z),p[0]-25,p[1]);}const grid=Array.from(new Set(pts.map(p=>p.arrival_load))).sort((a,b)=>a-b),batchGrid=Array.from(new Set(pts.map(p=>p.batch_size))).sort((a,b)=>a-b),by=new Map(pts.map(p=>[`${p.arrival_load},${p.batch_size}`,p]));for(let i=0;i<grid.length-1;i++)for(let j=0;j<batchGrid.length-1;j++){const corners=[[grid[i],batchGrid[j]],[grid[i+1],batchGrid[j]],[grid[i+1],batchGrid[j+1]],[grid[i],batchGrid[j+1]]].map(([a,b])=>by.get(`${a},${b}`));if(corners.every(p=>p&&p.algorithms?.[$('surfaceAlgorithm').value]?.status!=='WIP_GROWTH_DETECTED'&&cellValue(p)!==null)){ctx.fillStyle=color(corners.reduce((s,p)=>s+cellValue(p),0)/4,min,max).replace(')', ' / .25)');ctx.strokeStyle='#39726c';ctx.beginPath();corners.forEach((p,k)=>{const pos=project(p.arrival_load,p.batch_size,cellValue(p));k?ctx.lineTo(...pos):ctx.moveTo(...pos)});ctx.closePath();ctx.fill();ctx.stroke()}}for(const p of pts){const v=cellValue(p),pos=project(p.arrival_load,p.batch_size,v??min);ctx.fillStyle=v===null?'#fbbf24':color(v,min,max);ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=2;if(v===null){ctx.beginPath();ctx.moveTo(pos[0]-5,pos[1]-5);ctx.lineTo(pos[0]+5,pos[1]+5);ctx.moveTo(pos[0]+5,pos[1]-5);ctx.lineTo(pos[0]-5,pos[1]+5);ctx.stroke()}else{ctx.beginPath();if(pointUnconfirmed(p)){ctx.moveTo(pos[0],pos[1]-6);ctx.lineTo(pos[0]+6,pos[1]);ctx.lineTo(pos[0],pos[1]+6);ctx.lineTo(pos[0]-6,pos[1]);ctx.closePath();ctx.stroke()}else{ctx.arc(...pos,5,0,Math.PI*2);ctx.fill()}}surfaceHits.push({x:pos[0]-10,y:pos[1]-10,w:20,h:20,p})}ctx.fillStyle='#9aafc8';ctx.fillText(pts.length?'בחירת נקודה מציגה דיוק, חימום ומקור':'הפעל ניסוי או טען תוצאת מחקר',400,410)}
function drawHeatmap(){const c=$('heatmap'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);heatHits=[];const pts=surfaceData?.points||[];const ax=Array.from(new Set(pts.map(p=>p.arrival_load))).sort((a,b)=>a-b),by=Array.from(new Set(pts.map(p=>p.batch_size))).sort((a,b)=>a-b);const vals=pts.map(cellValue).filter(v=>v!==null),min=Math.min(0,...vals),max=Math.max(1,...vals);ctx.font='14px Segoe UI';ctx.textAlign='center';ctx.fillStyle='#b5c8de';ctx.fillText('Arrival load ×',345,425);ctx.fillText(metricLabel(),325,25);ctx.save();ctx.translate(23,220);ctx.rotate(-Math.PI/2);ctx.fillText('Batch size ×',0,0);ctx.restore();if(!pts.length){ctx.fillText('אותם נתונים, מבט נוסף',325,220);return}const width=510/ax.length,height=315/by.length;for(const p of pts){const x=85+ax.indexOf(p.arrival_load)*width,y=55+(by.length-1-by.indexOf(p.batch_size))*height,v=cellValue(p);ctx.fillStyle=v===null?'#1c2c40':color(v,min,max);ctx.fillRect(x+3,y+3,width-6,height-6);ctx.fillStyle=v===null?'#fbbf24':'#062726';ctx.font='16px Consolas';ctx.fillText(v===null?'×':format(v)+(pointUnconfirmed(p)?' ◇':''),x+width/2,y+height/2+6);heatHits.push({x,y,w:width,h:height,p})}ctx.fillStyle='#b5c8de';ctx.font='14px Consolas';ax.forEach((v,i)=>ctx.fillText(v,85+(i+.5)*width,395));by.forEach((v,i)=>ctx.fillText(v,60,55+(by.length-i-.5)*height+5))}
function hit(canvas,event,boxes){const r=canvas.getBoundingClientRect(),x=(event.clientX-r.left)*canvas.width/r.width,y=(event.clientY-r.top)*canvas.height/r.height;return [...boxes].reverse().find(b=>x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h)}
$('floor').onclick=e=>{const h=hit($('floor'),e,hitboxes);if(h)select(h.type,h.id)};
$('surface').onclick=e=>{const h=hit($('surface'),e,surfaceHits);if(h)$('pointDetails').textContent=pointText(h.p)};
$('heatmap').onclick=e=>{const h=hit($('heatmap'),e,heatHits);if(h)$('pointDetails').textContent=pointText(h.p)};
let drag=null;$('surface').onpointerdown=e=>{drag=e.clientX;$('surface').setPointerCapture(e.pointerId)};$('surface').onpointermove=e=>{if(drag!==null){yaw+=(e.clientX-drag)*.007;drag=e.clientX;drawSurface()}};$('surface').onpointerup=()=>{drag=null};
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{currentTab=b.dataset.tab;selected=null;for(const btn of document.querySelectorAll('[data-tab]'))btn.setAttribute('aria-selected',String(btn===b));$('inspector').innerHTML='<p class="muted">בחר ישות להצגת פרטים.</p>';renderEntities()};
$('zoom').onchange=()=>{$('floor').style.width=(+$('zoom').value*100)+'%'};$('search').oninput=renderEntities;$('arrivalLoad').oninput=()=>$('loadOut').textContent='×'+(+$('arrivalLoad').value).toFixed(2);$('batchSize').oninput=()=>$('batchOut').textContent='×'+(+$('batchSize').value).toFixed(2);
$('run').onclick=()=>run('run');$('scenario').onclick=()=>run('scenario');$('grid').onclick=()=>run('grid');$('cancel').onclick=()=>api('/api/cancel/'+taskId,{}).then(x=>$('progress').textContent=x.message).catch(e=>notice(e.message,true));
$('seek').oninput=()=>{if(result){time=Math.max(result.trace.start_min||0,Math.min(result.trace.end_min,+$('seek').value||0));drawFloor();updateClock();renderEntities()}};$('play').onclick=()=>{if(time>=result.trace.end_min)time=result.trace.start_min||0;playing=!playing;$('play').textContent=playing?'Ⅱ השהה':'▶ הפעל שחזור'};$('scrub').oninput=()=>{time=+$('scrub').value;drawFloor();updateClock();renderEntities()};$('next').onclick=()=>{const next=result.trace.events.find(e=>e.time>time+.00001);if(next){time=next.time;drawFloor();updateClock();renderEntities()}};
$('pointSelect').onchange=()=>{const i=$('pointSelect').value;if(i!=='')$('pointDetails').textContent=pointText(surfaceData.points[+i])};$('surfaceAlgorithm').onchange=renderSurfaces;$('view').onchange=renderSurfaces;
