$('upload').onchange=async()=>{try{const data=JSON.parse(await $('upload').files[0].text());data.trace?loadRun(data):loadSurface(data)}catch(e){notice('טעינת הקובץ נכשלה: '+e.message,true)}};
async function init(){const replay=new URLSearchParams(location.search).get('replay');if(replay){try{const r=await fetch(replay);loadRun(await r.json())}catch(e){notice('טעינת השחזור נכשלה: '+e.message,true)}}drawFloor();renderSurfaces();busy(false);try{const data=await api('/api/config');connected=data.app_version==='0.5.3';if(!connected)notice('הממשק חדש אך שרת Python ישן. יש לעצור ולהפעיל מחדש את השרת לפני הרצה.',true);if(data.operating_point?.status==='CALIBRATED')$('warmup').value=data.operating_point.warmup_days;machineLayout=data.machines;api('/api/world').then(w=>{worldData=w;nodeCoords=w.walking_graph.nodes;renderWorldTable()}).catch(()=>{});$('machineCount').textContent=machineLayout.length+' מכונות';$('connection').textContent='ממשק 0.5.3 · שרת '+(data.app_version||'ישן — נדרשת הפעלה מחדש')+' · מזהה '+(data.server_instance||'—')+' · '+data.templates+' משפחות · '+(data.demand?.baseline_status||'כיול טרם אושר');$('provenance').textContent='World '+data.world_version+' · Dataset '+data.dataset_sha256.slice(0,16);drawFloor();renderEntities();busy(false)}catch{$('connection').textContent='ממשק 0.5.3 · אין שרת Python — צפייה בלבד';notice('להרצה מקומית: python run_factory.py. אפשר לצפות כאן בתוצאת JSON שמורה.');busy(false)}requestAnimationFrame(frame)}
init();

let worldData=null;
function renderWorldTable(){
 if(!worldData)return;
 const w=worldData,kind=$('worldTable').value;
 const rows=kind==='families'?w.part_families.map(p=>({PartFamily:p.id,Complexity:p.complexity,Probability:p.demand_probability,QuantityDistribution:p.quantity_distribution,QuantityParameters:p.quantity_parameters||p.quantity_values,QuantityMean:p.quantity_mean??null})):
 kind==='operations'?w.part_families.flatMap(p=>p.operations.map(o=>({PartFamily:p.id,Position:o.position,Operation:o.id,Name:o.name,Family:o.machine_family,RequiredAxes:o.required_axes??'',SetupClass:o.setup_class,Eligible:o.eligible_machines.join(', '),Modifier:o.operation_modifier}))):
 kind==='machines'?w.machines:kind==='processing'?w.processing_matrix:kind==='setup'?w.setup_matrices:
 kind==='resources'?Object.entries({...w.resources,...w.provenance}).map(([Parameter,Value])=>({Parameter,Value})):
 w.part_families.map(p=>({PartFamily:p.id,Probability:p.demand_probability,ArrivalModel:w.demand.arrival_model,Lambda0:w.demand.baseline_jobs_per_day,QuantityDistribution:p.quantity_distribution,QuantityParameters:p.quantity_parameters||p.quantity_values}));
 if(!rows.length)return;const cols=Object.keys(rows[0]);$('worldTables').innerHTML='<table dir="ltr"><thead><tr>'+cols.map(c=>'<th>'+escape(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+escape(typeof r[c]==='number'?format(r[c],5):Array.isArray(r[c])?r[c].join(', '):typeof r[c]==='object'?JSON.stringify(r[c]):r[c])+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
}
$('worldTable').onchange=renderWorldTable;
$('replications').oninput=renderRunCount;$('gridValues').oninput=renderRunCount;renderRunCount();

function renderFamilyMetrics(data){
 const rows=Object.entries(data.per_family||{});
 for(const axes of [3,4]){
  const machines=(data.machines||[]).filter(m=>m.machine_family==='Milling'&&m.axis_capability===axes);
  if(!machines.length)continue;
  const denominator=data.measurement?.denominator_min||1;
  rows.push(['Milling · '+axes+' axes (physical)',{machine_count:machines.length,processing_utilization:machines.reduce((v,m)=>v+(data.state_minutes?.machine?.[m.id]?.PROCESSING||0),0)/(denominator*machines.length),busy_utilization:machines.reduce((v,m)=>v+(data.per_machine_utilization?.[m.id]||0),0)/machines.length,mean_ready_queue:null}]);
 }
 $('familyMetrics').innerHTML=rows.length?'<table><thead><tr><th>Machine family</th><th>Machines</th><th>Processing / calendar</th><th>Service / calendar</th><th>Occupied / calendar</th><th>Waiting / calendar</th><th>Mean ready queue</th></tr></thead><tbody>'+rows.map(([f,r])=>'<tr><td>'+escape(f)+'</td><td>'+r.machine_count+'</td><td>'+format(100*r.processing_utilization)+'%</td><td>'+format(100*r.busy_utilization)+'%</td><td>'+format(r.occupied_utilization==null?null:100*r.occupied_utilization)+'%</td><td>'+format(r.waiting_utilization==null?null:100*r.waiting_utilization)+'%</td><td>'+format(r.mean_ready_queue)+'</td></tr>').join('')+'</tbody></table>':'';
}

function renderLive(data,status){
 liveData=data;time=data.time;playing=false;
 const m=data.machines,w=data.workers,ops=w.filter(x=>!x.kind.startsWith('setup')),setup=w.filter(x=>x.kind.startsWith('setup'));
 const available=xs=>xs.filter(x=>x.available).length;
 const metrics=[['עובדים רגילים פנויים',available(ops)],['רגילים במשמרת (כולל הפסקות)',ops.filter(x=>x.active).length],['מומחי Setup פנויים',available(setup)],['מכונות מעבדות',m.filter(x=>x.state==='PROCESSING').length],['מכונות בהכנה',m.filter(x=>x.state==='SETUP').length],['מכונות ממתינות',m.filter(x=>x.state.startsWith('WAITING')).length],['מכונות בטיפול ידני',m.filter(x=>['LOADING','UNLOADING','CYCLE_CHANGE'].includes(x.state)).length],['מכונות פנויות',m.filter(x=>x.state==='IDLE_AVAILABLE').length],['עבודות במערכת',data.released-data.completed]];
 $('liveResources').innerHTML=metrics.map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('');
 const phase={warmup:'חימום',measurement:'מדידה',drain:'ניקוז'}[data.phase];
 $('liveProgress').textContent=`${status==='RUNNING'?'ריצה פעילה':'מצב אחרון — '+status} · ${data.algorithm} · חזרה ${data.replication+1} · הגעה ×${data.arrival_scale} · כמות ×${data.batch_scale} · ${phase} · יום ${format(data.time/1440,2)} · ${format(data.elapsed_seconds,0)} שניות מחשב · ${format(data.time/Math.max(.001,data.elapsed_seconds))} דקות סימולציה לשנייה · ${data.phase==='drain'?'נותרו '+(data.released-data.completed)+' עבודות':format(100*data.time/data.window_end)+'% מחלון החימום והמדידה'} · ${format(data.events,0)} אירועים`;
 $('liveJobs').innerHTML='<table><tr><th>עבודה</th><th>משפחה</th><th>כמות</th><th>פעולה</th><th>מצב</th><th>מכונה / מיקום</th></tr>'+data.jobs.map(j=>`<tr><td><button data-live-job="${escape(j.id)}">${escape(j.id)}</button></td><td>${escape(j.item)}</td><td>${j.quantity}</td><td>${escape(j.batches.map(b=>b.operation).join(', '))}</td><td>${escape(j.batches.map(b=>labels[b.state]||b.state).join(', '))}</td><td>${escape(j.batches.map(b=>b.machine||b.location||'תור משותף').join(', '))}</td></tr>`).join('')+'</table>';
 for(const b of $('liveJobs').querySelectorAll('button'))b.onclick=()=>{liveJobId=b.dataset.liveJob;renderLiveJob()};
 renderLiveJob();renderEntities();renderQueueCounts(data.ready_queue_by_family);$('clock').textContent='LIVE · יום '+format(time/1440,2);$('empty').style.display='none';drawFloor();
}
function renderLiveJob(){
 const j=liveData?.jobs.find(j=>j.id===liveJobId);if(!j){$('liveJobDetails').textContent=liveJobId?'העבודה אינה פעילה עוד בתמונת המצב הנוכחית.':'בחרו עבודה לפירוט לפי פעולה.';return;}
 const family=worldData?.part_families.find(p=>p.id===j.item);
 $('liveJobDetails').innerHTML=`<h3>${escape(j.id)} · ${j.quantity} חלקים · שהייה עד כה ${format((liveData.time-j.release)/60)} שעות</h3><table><tr><th>פעולה</th><th>שם</th><th>סיימו / נדרשים</th><th>מצב</th><th>גודל מחזור פעיל</th><th>אחראי</th></tr>`+j.route.map(op=>{const b=j.batches.find(b=>b.operation===op),o=family?.operations.find(o=>o.id===op);return `<tr><td>${escape(op)}</td><td>${escape(o?.name||'')}</td><td>${j.operation_counts[op]||0} / ${j.quantity}</td><td>${escape(b?(labels[b.state]||b.state):(j.operation_counts[op]===j.quantity?'הושלמה':'טרם התחילה'))}</td><td>${b&&['PROCESSING','WAITING_FOR_WORKER_UNLOAD','UNLOADING','WAITING_FOR_CYCLE_CHANGE','CYCLE_CHANGE'].includes(b.state)?b.cycle_quantity:'—'}</td><td>${escape(b?.owner||'—')}</td></tr>`}).join('')+'</table><p>ספירת הסיום היא לאחר פריקה בכל פעולה; אין לחבר ספירות מפעולות שונות לכמות החלקים בעבודה.</p>';
}
Object.assign(labels,{WAITING_SETUP:'ממתינה למומחה Setup',WAITING_TRANSPORT:'ממתינה לשינוע',READY:'ממתינה להקצאה',COMPLETE:'הושלמה'});
$('savedSurface').onclick=async()=>{try{loadSurface(await api('/api/surface'))}catch(e){notice(e.message,true)}};

function renderOperationHistory(j){
 const initial=result.trace.initial?.operation_counts?.[j.id];
 const family=worldData?.part_families.find(p=>p.id===j.item);
 const rows=j.route.map(op=>{const events=(result.trace.events||[]).filter(e=>e.job===j.id&&e.operation===op&&e.kind==='parts_unloaded'&&e.time<=time);const known=initial!==undefined||(result.trace.start_min||0)===0||j.release>=(result.trace.start_min||0);const count=known?(initial?.[op]||0)+events.reduce((n,e)=>n+e.hi-e.lo,0):null;const active=(result.batches||[]).filter(b=>b.job===j.id&&j.route[b.op_index]===op).flatMap(b=>[...tracks.keys()].map(id=>intervalAt(id)).filter(i=>i?.batch===b.id));return `<tr><td>${escape(op)} ${escape(family?.operations.find(o=>o.id===op)?.name||'')}</td><td>${count===null?'לא ידוע לפני חלון השחזור':count+' / '+j.quantity}</td><td>${escape(active.map(i=>i.entity+': '+(labels[i.state]||i.state)).join(', ')|| (count===j.quantity?'הושלמה':'אין פעילות מתועדת ברגע זה'))}</td></tr>`});
 $('inspector').innerHTML+='<table><tr><th>פעולה</th><th>פריקות שהושלמו</th><th>פעילות עכשיו</th></tr>'+rows.join('')+'</table>';
}

function syncRunControls(c){
 for(const [id,key] of [['arrivalLoad','arrival_load'],['batchSize','batch_size'],['horizon','horizon_days']]){
  const e=$(id),v=String(c[key]);
  if(id==='horizon'&&e.options&&!Array.from(e.options).some(o=>o.value===v)){const o=document.createElement('option');o.value=v;o.textContent=v+' ימים · מהתוצאה';e.appendChild(o)}
  if(id!=='horizon'){e.min=Math.min(+e.min,c[key]);e.max=Math.max(+e.max,c[key]);e.step='any'}e.value=v;
 }
 $('loadOut').textContent='×'+format(c.arrival_load,2);$('batchOut').textContent='×'+format(c.batch_size,2);
}
function downloadJSON(data,name){if(!data)return;const url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function snapshotAtTime(){let found=null;for(const s of result?.trace.snapshots||[]){if(s.time>time)break;found=s}return found}
function renderQueueCounts(counts){$('queueCounts').innerHTML=counts?'<span>מנות מוכנות בתור לפי קבוצת מכונות:</span>'+Object.entries(counts).sort().map(([f,n])=>'<span class="queue-badge"><b dir="ltr">'+escape(f)+'</b> '+n+'</span>').join(''):'מוני תורים יופיעו בהרצה חדשה; לא הוסקו מקומות פיזיים למנות.';}
function metricLabel(){return {surface:'Mean flow (hours)',delta:'Difference vs FIFO (hours)',improvement:'Improvement vs FIFO (%)'}[$('view').value]||'Mean flow (hours)'}
function pointUnconfirmed(p){return (p.algorithms?.[$('surfaceAlgorithm').value]?.status||p.status)!=='PRECISION_MET'}
function renderRunCount(){const n=$('gridValues').value.split(',').length,r=+$('replications').value;$('runCount').textContent=n+' × '+n+' נקודות · 2 אלגוריתמים · '+r+' חזרות = '+(n*n*2*r)+' ריצות ברשת. חימום מוציא את תחילת הריצה מהמדדים; אינו מוכיח יציבות.';}

for(const tab of document.querySelectorAll('[data-tab]'))tab.onkeydown=e=>{
 const tabs=Array.from(document.querySelectorAll('[data-tab]')),i=tabs.indexOf(tab);
 const n=e.key==='ArrowLeft'?(i+1)%tabs.length:e.key==='ArrowRight'?(i+tabs.length-1)%tabs.length:e.key==='Home'?0:e.key==='End'?tabs.length-1:null;
 if(n!==null){e.preventDefault();tabs[n].click();tabs[n].focus()}
};
